def count_nodes_equal_to_descendants(root):
    answer = 0
    def subtree(node):
        nonlocal answer
        if node is None:
            return 0
        descendant_sum = subtree(node.left) + subtree(node.right)
        if node.val == descendant_sum:
            answer += 1
        return node.val + descendant_sum
    subtree(root)
    return answer

